#!/usr/bin/env python3
import argparse
import json
import os
import stat
import subprocess
from dataclasses import dataclass, asdict
from pathlib import Path

@dataclass
class Finding:
    control: str
    status: str
    evidence: str
    recommendation: str

def run(command):
    try:
        result = subprocess.run(command, text=True, capture_output=True, check=False)
        return result.returncode, result.stdout.strip(), result.stderr.strip()
    except OSError as exc:
        return 127, "", str(exc)

def check_root_login():
    rc, out, err = run(["sh", "-c", "awk -F: '$1==\"root\" {print $7}' /etc/passwd 2>/dev/null"] )
    if rc != 0:
        return Finding("AUTH-01", "unknown", err or "Unable to read /etc/passwd", "Verify the root account shell according to the approved baseline.")
    shell = out or ""
    if shell in {"/usr/sbin/nologin", "/sbin/nologin", "/bin/false", ""}:
        return Finding("AUTH-01", "pass", f"root shell={shell}", "No action required.")
    return Finding("AUTH-01", "review", f"root shell={shell}", "Review whether direct root login is required and restrict interactive use where possible.")

def check_world_writable_etc():
    path = Path("/etc")
    if not path.exists():
        return Finding("FS-01", "unknown", "/etc not present", "Run the audit on a Linux system with /etc.")
    suspicious = []
    for entry in path.iterdir():
        try:
            mode = entry.stat().st_mode
        except OSError:
            continue
        if stat.S_ISREG(mode) and mode & stat.S_IWOTH:
            suspicious.append(entry.name)
    if not suspicious:
        return Finding("FS-01", "pass", "No world-writable regular files found directly under /etc", "No action required.")
    return Finding("FS-01", "fail", ", ".join(sorted(suspicious)[:20]), "Remove unnecessary world-write permission after validating application requirements.")

def check_ssh_config():
    candidates = [Path("/etc/ssh/sshd_config")]
    for path in candidates:
        if path.exists():
            text = path.read_text(encoding="utf-8", errors="replace")
            password_auth = None
            root_login = None
            for raw in text.splitlines():
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                parts = line.split(None, 1)
                if len(parts) != 2:
                    continue
                key, value = parts[0].lower(), parts[1].strip().lower()
                if key == "passwordauthentication":
                    password_auth = value
                elif key == "permitrootlogin":
                    root_login = value
            evidence = f"PasswordAuthentication={password_auth}; PermitRootLogin={root_login}"
            if password_auth == "no" and root_login in {"no", "prohibit-password", "without-password"}:
                return Finding("SSH-01", "pass", evidence, "No action required.")
            return Finding("SSH-01", "review", evidence, "Review SSH authentication and root-login settings against the approved management baseline.")
    return Finding("SSH-01", "unknown", "No /etc/ssh/sshd_config found", "Verify SSH configuration using the platform's supported configuration source.")

def check_updates():
    if Path("/usr/bin/apt-get").exists() or Path("/usr/bin/dnf").exists() or Path("/usr/bin/yum").exists():
        return Finding("PATCH-01", "review", "Package manager detected; this script does not query remote repositories", "Use the organization's approved patch process to verify current security updates.")
    return Finding("PATCH-01", "unknown", "No supported package manager detected by this training check", "Verify patch posture using the operating system's package-management process.")

def main():
    parser = argparse.ArgumentParser(description="Local-only System Security Baseline Auditor")
    parser.add_argument("--json", type=Path, help="Write a JSON report to this path")
    args = parser.parse_args()

    findings = [
        check_root_login(),
        check_world_writable_etc(),
        check_ssh_config(),
        check_updates(),
    ]
    report = {
        "tool_scope": "local-only, read-only training audit",
        "finding_count": len(findings),
        "findings": [asdict(item) for item in findings],
    }
    text = json.dumps(report, indent=2)
    if args.json:
        args.json.write_text(text + "\n", encoding="utf-8")
    else:
        print(text)

if __name__ == "__main__":
    main()
